7	import { spawn } from 'node:child_process';
8	import { type FileSystemService } from './fileSystemService.js';
9	import { type SandboxManager } from './sandboxManager.js';
10	import { debugLogger } from '../utils/debugLogger.js';
11	import { isNodeError } from '../utils/errors.js';
12	
13	/**
14	 * A FileSystemService implementation that performs operations through a sandbox.
15	 */
16	export class SandboxedFileSystemService implements FileSystemService {
17	  constructor(
18	    private sandboxManager: SandboxManager,
19	    private cwd: string,
20	  ) {}
21	
22	  async readTextFile(filePath: string): Promise<string> {
23	    const prepared = await this.sandboxManager.prepareCommand({
24	      command: '__read',
25	      args: [filePath],
26	      cwd: this.cwd,
27	      env: process.env,
28	    });
29	
30	    return new Promise((resolve, reject) => {
31	      // Direct spawn is necessary here for streaming large file contents.
32	
33	      const child = spawn(prepared.program, prepared.args, {
34	        cwd: this.cwd,
35	        env: prepared.env,
36	      });
37	
38	      let output = '';
39	      let error = '';
40	
41	      child.stdout?.on('data', (data) => {
42	        output += data.toString();
43	      });
44	
45	      child.stderr?.on('data', (data) => {
46	        error += data.toString();
47	      });
48	
49	      child.on('close', (code) => {
50	        if (code === 0) {
51	          resolve(output);
52	        } else {
53	          reject(
54	            new Error(
55	              `Sandbox Error: read_file failed for '${filePath}'. Exit code ${code}. ${error ? 'Details: ' + error : ''}`,
56	            ),
57	          );
58	        }
59	      });
60	
61	      child.on('error', (err) => {
62	        reject(
63	          new Error(
64	            `Sandbox Error: Failed to spawn read_file for '${filePath}': ${err.message}`,
65	          ),
66	        );
67	      });
68	    });
69	  }
70	
71	  async writeTextFile(filePath: string, content: string): Promise<void> {
72	    const prepared = await this.sandboxManager.prepareCommand({
73	      command: '__write',
74	      args: [filePath],
75	      cwd: this.cwd,
76	      env: process.env,
77	    });
78	
79	    return new Promise((resolve, reject) => {
80	      // Direct spawn is necessary here for streaming large file contents.
81	
82	      const child = spawn(prepared.program, prepared.args, {
83	        cwd: this.cwd,
84	        env: prepared.env,
85	      });
86	
87	      child.stdin?.on('error', (err) => {
88	        // Silently ignore EPIPE errors on stdin, they will be caught by the process error/close listeners
89	        if (isNodeError(err) && err.code === 'EPIPE') {
90	          return;
91	        }
92	        debugLogger.error(
93	          `Sandbox Error: stdin error for '${filePath}': ${
94	            err instanceof Error ? err.message : String(err)
95	          }`,
96	        );
97	      });
98	
99	      child.stdin?.write(content);
100	      child.stdin?.end();
101	
102	      let error = '';
103	      child.stderr?.on('data', (data) => {
104	        error += data.toString();
105	      });
106	
107	      child.on('close', (code) => {
108	        if (code === 0) {
109	          resolve();
110	        } else {
111	          reject(
112	            new Error(
113	              `Sandbox Error: write_file failed for '${filePath}'. Exit code ${code}. ${error ? 'Details: ' + error : ''}`,
114	            ),
115	          );
116	        }
117	      });
118	
119	      child.on('error', (err) => {
120	        reject(
121	          new Error(
122	            `Sandbox Error: Failed to spawn write_file for '${filePath}': ${err.message}`,
123	          ),
124	        );
125	      });
126	    });
127	  }
128	}
