146	/**
147	 * Files that represent the governance or "constitution" of the repository
148	 * and should be write-protected in any sandbox.
149	 */
150	export const GOVERNANCE_FILES = [
151	  { path: '.gitignore', isDirectory: false },
152	  { path: '.geminiignore', isDirectory: false },
153	  { path: '.git', isDirectory: true },
154	] as const;
155	
156	/**
157	 * Files that contain sensitive secrets or credentials and should be
158	 * completely hidden (deny read/write) in any sandbox.
159	 */
160	export const SECRET_FILES = [
161	  { pattern: '.env' },
162	  { pattern: '.env.*' },
163	] as const;
164	
165	/**
166	 * Checks if a given file name matches any of the secret file patterns.
167	 */
168	export function isSecretFile(fileName: string): boolean {
169	  return SECRET_FILES.some((s) => {
170	    if (s.pattern.endsWith('*')) {
171	      const prefix = s.pattern.slice(0, -1);
172	      return fileName.startsWith(prefix);
173	    }
174	    return fileName === s.pattern;
175	  });
176	}
177	
178	/**
179	 * Returns arguments for the Linux 'find' command to locate secret files.
180	 */
181	export function getSecretFileFindArgs(): string[] {
182	  const args: string[] = ['('];
183	  SECRET_FILES.forEach((s, i) => {
184	    if (i > 0) args.push('-o');
185	    args.push('-name', s.pattern);
186	  });
187	  args.push(')');
188	  return args;
189	}
